import CryptoKit
import Foundation
import PDFCore
@testable import PDFEditing
import Security
import Testing

/// SIG-02/SIG-03 fixture builder. Signs test DER with keys generated by
/// TestSigningMaterial (temporary keychain/openssl) so the production parsers
/// and Security-backed verifiers are exercised with real signatures, not
/// hand-crafted "valid" bits.
struct EvidenceSigner: @unchecked Sendable {
  let material: TestSigningMaterial

  static func make(commonName: String = "sPDF Evidence Test") throws -> EvidenceSigner? {
    guard let material = try TestSigningMaterial.make(commonName: commonName) else {
      return nil
    }
    return EvidenceSigner(material: material)
  }

  var leafCertificate: SecCertificate? { PDFSigningIdentity.certificate(of: material.identity) }
  var leafDER: Data {
    leafCertificate.map { SecCertificateCopyData($0) as Data } ?? Data()
  }
  var issuerDER: Data { SecCertificateCopyData(material.caCertificate) as Data }
  var caKeyPath: String { material.directory.appendingPathComponent("ca.key").path }

  func cleanUp() { material.cleanUp() }

  func caSignature(over data: Data) throws -> Data {
    try EvidenceFixtures.opensslSign(data, keyPath: caKeyPath)
  }

  func leafSignature(over data: Data) throws -> Data {
    var key: SecKey?
    guard SecIdentityCopyPrivateKey(material.identity, &key) == errSecSuccess, let key else {
      throw PDFError(.malformed, "Evidence test identity has no private key")
    }
    var error: Unmanaged<CFError>?
    guard let signature = SecKeyCreateSignature(
      key, .rsaSignatureMessagePKCS1v15SHA256, data as CFData, &error)
    else {
      throw PDFError(.malformed, "Evidence test identity refused to sign")
    }
    return signature as Data
  }
}

/// Authority used by signing tests; the closure sees the complete request DER.
struct MockTimestampAuthority: TimestampAuthority {
  let handler: @Sendable (Data) throws -> Data
  func timestampResponse(for requestDER: Data) throws -> Data { try handler(requestDER) }
}

final class EvidenceCounter: @unchecked Sendable {
  private let lock = NSLock()
  private var value = 0
  func increment() { lock.withLock { value += 1 } }
  var count: Int { lock.withLock { value } }
}

struct StubNetworkClient: SignatureNetworkClient {
  let response: Data
  let failure: PDFError?
  let counter: EvidenceCounter

  init(response: Data = Data(), failure: PDFError? = nil, counter: EvidenceCounter) {
    self.response = response
    self.failure = failure
    self.counter = counter
  }

  func fetch(url: URL, body: Data) throws -> Data {
    counter.increment()
    if let failure { throw failure }
    return response
  }
}

enum EvidenceFixtures {
  static let sha256OID = "2.16.840.1.101.3.4.2.1"
  static let timestampInfoOID = "1.2.840.113549.1.9.16.1.4"
  static let signedDataOID = "1.2.840.113549.1.7.2"
  static let contentTypeAttributeOID = "1.2.840.113549.1.9.3"
  static let messageDigestAttributeOID = "1.2.840.113549.1.9.4"
  static let signingTimeAttributeOID = "1.2.840.113549.1.9.5"
  static let rsaEncryptionOID = "1.2.840.113549.1.1.1"
  static let sha256WithRSAOID = "1.2.840.113549.1.1.11"
  static let ocspBasicOID = "1.3.6.1.5.5.7.48.1.1"
  static let policyOID = "1.3.6.1.4.1.99999.1"

  static func algorithmIdentifier(_ oid: String) -> Data {
    DER.sequence([DER.oid(oid), DER.null()])
  }

  static func rawContent(_ element: Data) -> Data {
    let bytes = [UInt8](element)
    var reader = DERReader(bytes: bytes)
    guard let parsed = try? reader.readElement(limits: PDFLimits()) else { return Data() }
    return Data(bytes[parsed.content.startIndex..<parsed.content.endIndex])
  }

  static func opensslSign(_ data: Data, keyPath: String) throws -> Data {
    let directory = FileManager.default.temporaryDirectory
      .appendingPathComponent(
        "spdf-evidence-sign-" + UUID().uuidString, isDirectory: true)
    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: directory) }
    let input = directory.appendingPathComponent("tbs.der")
    let output = directory.appendingPathComponent("signature.bin")
    try data.write(to: input)
    let process = Process()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/openssl")
    process.arguments = [
      "dgst", "-sha256", "-sign", keyPath, "-out", output.path, input.path,
    ]
    process.standardError = Pipe()
    process.standardOutput = Pipe()
    try process.run()
    process.waitUntilExit()
    guard process.terminationStatus == 0 else {
      throw PDFError(.malformed, "openssl could not sign an evidence fixture")
    }
    return try Data(contentsOf: output)
  }

  @discardableResult
  static func openssl(_ arguments: [String]) throws -> (status: Int32, output: String) {
    let process = Process()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/openssl")
    process.arguments = arguments
    let output = Pipe()
    let errorPipe = Pipe()
    process.standardOutput = output
    process.standardError = errorPipe
    try process.run()
    process.waitUntilExit()
    let stdout = String(decoding: output.fileHandleForReading.readDataToEndOfFile(), as: UTF8.self)
    let stderr = String(
      decoding: errorPipe.fileHandleForReading.readDataToEndOfFile(), as: UTF8.self)
    return (process.terminationStatus, stdout + stderr)
  }

  private static func temporaryFile(named name: String, contents: Data) throws -> URL {
    let directory = FileManager.default.temporaryDirectory
      .appendingPathComponent("spdf-evidence-verify-" + UUID().uuidString, isDirectory: true)
    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    let url = directory.appendingPathComponent(name)
    try contents.write(to: url)
    return url
  }

  /// Independent check: OpenSSL must accept the token's CMS signature under
  /// the TSA CA. Returns nil when openssl is unavailable.
  static func opensslVerifiesTimestampToken(_ token: Data, caPEM: Data) throws -> Bool? {
    guard FileManager.default.isExecutableFile(atPath: "/usr/bin/openssl") else { return nil }
    let tokenURL = try temporaryFile(named: "token.der", contents: token)
    let caURL = try temporaryFile(named: "ca.pem", contents: caPEM)
    defer { try? FileManager.default.removeItem(at: tokenURL.deletingLastPathComponent()) }
    let result = try openssl([
      "cms", "-verify", "-binary", "-inform", "DER", "-in", tokenURL.path,
      "-CAfile", caURL.path, "-purpose", "any", "-out", "/dev/null",
    ])
    return result.status == 0
  }

  /// Independent check: OpenSSL must verify the OCSP response and report the
  /// leaf status. Returns nil when openssl is unavailable.
  static func opensslVerifiesOCSP(_ response: Data, signer: EvidenceSigner) throws -> Bool? {
    guard FileManager.default.isExecutableFile(atPath: "/usr/bin/openssl") else { return nil }
    let responseURL = try temporaryFile(named: "response.der", contents: response)
    let caURL = try temporaryFile(named: "ca.pem", contents: signer.material.caPEM)
    let leafPEM = try Data(
      contentsOf: signer.material.directory.appendingPathComponent("leaf.pem"))
    let leafURL = try temporaryFile(named: "leaf.pem", contents: leafPEM)
    defer { try? FileManager.default.removeItem(at: responseURL.deletingLastPathComponent()) }
    let result = try openssl([
      "ocsp", "-respin", responseURL.path, "-issuer", caURL.path,
      "-cert", leafURL.path, "-CAfile", caURL.path, "-no_nonce",
    ])
    return result.output.contains("Response verify OK")
  }

  /// Independent check: OpenSSL must verify the CRL signature under the CA.
  static func opensslVerifiesCRL(_ crl: Data, signer: EvidenceSigner) throws -> Bool? {
    guard FileManager.default.isExecutableFile(atPath: "/usr/bin/openssl") else { return nil }
    let crlURL = try temporaryFile(named: "crl.der", contents: crl)
    let caURL = try temporaryFile(named: "ca.pem", contents: signer.material.caPEM)
    defer { try? FileManager.default.removeItem(at: crlURL.deletingLastPathComponent()) }
    let result = try openssl([
      "crl", "-in", crlURL.path, "-inform", "DER", "-CAfile", caURL.path,
      "-noout", "-verify",
    ])
    return result.status == 0 && result.output.contains("verify OK")
  }

  /// Complete RFC 3161 timestamp-token ContentInfo signed by the TSA identity.
  static func timestampToken(
    imprint: Data, nonce: Data?, genTime: Date, signer: EvidenceSigner,
    policy: String = policyOID, serial: Int = 7
  ) throws -> Data {
    guard let certificate = signer.leafCertificate,
      let (issuerDER, serialDER) = CMSSigner.issuerAndSerial(certificate: certificate)
    else {
      throw PDFError(.malformed, "Evidence TSA certificate could not be parsed")
    }
    var tstInfoParts: [Data] = [
      DER.integer(1),
      DER.oid(policy),
      DER.sequence([
        DER.sequence([DER.oid(sha256OID), DER.null()]),
        DER.octetString(imprint),
      ]),
      DER.integer(serial),
      DER.generalizedTime(genTime),
    ]
    if let nonce { tstInfoParts.append(DER.integerBytes(nonce)) }
    let tstInfo = DER.sequence(tstInfoParts)

    let attributes = [
      DER.sequence([
        DER.oid(contentTypeAttributeOID), DER.set([DER.oid(timestampInfoOID)]),
      ]),
      DER.sequence([
        DER.oid(messageDigestAttributeOID),
        DER.set([DER.octetString(Data(SHA256.hash(data: tstInfo)))]),
      ]),
      DER.sequence([
        DER.oid(signingTimeAttributeOID), DER.set([DER.utcTime(genTime)]),
      ]),
    ].sorted { $0.lexicographicallyPrecedes($1) }
    let attributeContent = DER.concatenated(attributes)
    let signedAttributes = DER.element(tag: 0x31, attributeContent)
    let signature = try signer.leafSignature(over: signedAttributes)
    let signerInfo = DER.sequence([
      DER.integer(1),
      DER.sequence([issuerDER, serialDER]),
      DER.sequence([DER.oid(sha256OID), DER.null()]),
      DER.element(tag: 0xA0, attributeContent),
      DER.sequence([DER.oid(sha256WithRSAOID), DER.null()]),
      DER.octetString(signature),
    ])
    let certificateSet = DER.element(
      tag: 0xA0,
      DER.concatenated(
        [signer.leafDER, signer.issuerDER].sorted { $0.lexicographicallyPrecedes($1) }))
    let encapsulated = DER.sequence([
      DER.oid(timestampInfoOID),
      DER.explicitContext(0, DER.octetString(tstInfo)),
    ])
    let signedData = DER.sequence([
      DER.integer(1),
      DER.set([algorithmIdentifier(sha256OID)]),
      encapsulated,
      certificateSet,
      DER.set([signerInfo]),
    ])
    return DER.sequence([
      DER.oid(signedDataOID), DER.explicitContext(0, signedData),
    ])
  }

  /// TimeStampResp: granted status plus the token (or a rejection status).
  static func timestampResponse(token: Data, granted: Bool = true) -> Data {
    let status = DER.sequence([DER.integer(granted ? 0 : 2)])
    if !granted { return DER.sequence([status]) }
    return DER.sequence([status, token])
  }
}

extension EvidenceFixtures {
  enum OCSPStatus {
    case good
    case revoked(Date)
    case unknown
  }

  /// Build a CA-signed OCSP basic response for the leaf certificate.
  static func ocspResponse(
    leaf: EvidenceSigner, status: OCSPStatus, thisUpdate: Date, nextUpdate: Date?,
    producedAt: Date = Date(), tamperSignature: Bool = false
  ) throws -> Data {
    let leafFields = try X509CertificateFields.parse(leaf.leafDER)
    let issuerFields = try X509CertificateFields.parse(leaf.issuerDER)
    let nameHash = Data(SHA256.hash(data: issuerFields.subjectDER))
    let keyHash = Data(SHA256.hash(data: issuerFields.subjectPublicKeyBits))
    let leafSerial = rawContent(leafFields.serialDER)
    let certID = DER.sequence([
      algorithmIdentifier(sha256OID),
      DER.octetString(nameHash),
      DER.octetString(keyHash),
      DER.integerBytes(leafSerial),
    ])
    let statusElement: Data
    switch status {
    case .good:
      statusElement = DER.element(tag: 0x80, Data())
    case .revoked(let time):
      statusElement = DER.element(tag: 0xA1, DER.generalizedTime(time))
    case .unknown:
      statusElement = DER.element(tag: 0x82, Data())
    }
    var singleParts: [Data] = [
      certID, statusElement, DER.generalizedTime(thisUpdate),
    ]
    if let nextUpdate {
      singleParts.append(DER.explicitContext(0, DER.generalizedTime(nextUpdate)))
    }
    let single = DER.sequence(singleParts)
    // responderID ::= CHOICE { byName [1] Name }; a tag on a CHOICE is
    // EXPLICIT, so the complete Name SEQUENCE is wrapped inside [1].
    let responderID = DER.element(tag: 0xA1, issuerFields.subjectDER)
    let tbs = DER.sequence([
      responderID,
      DER.generalizedTime(producedAt),
      DER.sequence([single]),
    ])
    var signature = try leaf.caSignature(over: tbs)
    if tamperSignature { signature = Data(signature.map { $0 ^ 0xFF }) }
    let basic = DER.sequence([
      tbs,
      algorithmIdentifier(sha256WithRSAOID),
      DER.bitString(signature),
      DER.explicitContext(0, DER.sequence([leaf.issuerDER])),
    ])
    return DER.sequence([
      DER.enumerated(0),
      DER.explicitContext(
        0, DER.sequence([DER.oid(ocspBasicOID), DER.octetString(basic)])),
    ])
  }

  /// Build a CA-signed DER CRL. revokedLeaf controls whether the leaf serial
  /// appears in the revoked list.
  static func crl(
    leaf: EvidenceSigner, revokedLeaf: Bool, thisUpdate: Date, nextUpdate: Date,
    tamperSignature: Bool = false
  ) throws -> Data {
    let leafFields = try X509CertificateFields.parse(leaf.leafDER)
    let issuerFields = try X509CertificateFields.parse(leaf.issuerDER)
    var tbsParts: [Data] = [
      DER.integer(1),
      algorithmIdentifier(sha256WithRSAOID),
      issuerFields.subjectDER,
      DER.utcTime(thisUpdate),
      DER.utcTime(nextUpdate),
    ]
    if revokedLeaf {
      let entry = DER.sequence([
        DER.integerBytes(rawContent(leafFields.serialDER)),
        DER.utcTime(thisUpdate),
      ])
      tbsParts.append(DER.sequence([entry]))
    } else {
      tbsParts.append(DER.sequence([]))
    }
    let tbs = DER.sequence(tbsParts)
    var signature = try leaf.caSignature(over: tbs)
    if tamperSignature { signature = Data(signature.map { $0 ^ 0xFF }) }
    return DER.sequence([
      tbs, algorithmIdentifier(sha256WithRSAOID), DER.bitString(signature),
    ])
  }

  /// Sign a blank PDF and return its source bytes plus the graph, for
  /// validation-evidence tests.
  static func signedBlankPDF(
    identity: SecIdentity, fieldName: String = "EvidenceSignature"
  ) throws -> (data: Data, graph: PDFGraph) {
    let parsed = try PDFParser.parse(BlankPDF.data(format: .letter))
    let options = PDFSigningOptions(
      fieldName: fieldName, pageIndex: 0, rect: [72, 72, 272, 112],
      signingTime: Date())
    let data = try PDFSigningWriter.sign(parsed.graph, identity: identity, options: options)
    return (data, try PDFParser.parse(data).graph)
  }
}
